import { readFile, writeFile } from 'node:fs/promises';
import { normalizeHeroes } from '../src/models/heroModel.js';
import { normalizeStatistics, filterLabel } from '../src/models/statisticsModel.js';
// Historical 70:30 report; final v2 report is generated by compare-final-meta.mjs.
import { attachMetaTiersV1 as attachMetaTiers, LEGACY_META_POLICY as META_POLICY } from '../src/domain/meta.js';
import { attachRoleTiers } from '../src/domain/tier.js';
const compareHeroCohorts = (key, heroes, cohorts) => cohorts.map(cohort => ({ ...cohort, hero: attachMetaTiers(heroes, cohort.records).find(hero => hero.key === key) }));

const evidence = JSON.parse(await readFile(new URL('../tests/fixtures/ranked-cohorts.json', import.meta.url), 'utf8'));
const heroes = normalizeHeroes(JSON.parse(await readFile(new URL('../tests/fixtures/overfast-heroes.json', import.meta.url), 'utf8')));
const cohorts = evidence.cases.filter(item => item.status === 200).map(item => ({ ...item, records: normalizeStatistics(item.raw) }));
const n = value => value == null ? '미제공' : Number(value).toFixed(2);
const targets = ['domina', 'winston', 'doomfist', 'dmon'];
const lines = ['# 실제 등급별 API 및 메타 가중치 비교', '', `수집 시작(UTC): ${evidence.collectedAt}. 각 표는 별도 API 응답으로 계산했으며 등급 간 평균·합산은 하지 않았습니다. 테스트 증거 파일은 tests/fixtures/ranked-cohorts.json입니다.`, '', '## 지원 등급과 응답', '', '| 조건 | HTTP | 영웅 수 | 픽률 1% 미만 | 다이아와 수치가 다른 영웅 수 |', '| --- | --- | --- | --- | --- |'];
const diamond = cohorts.find(item => item.filters.region === 'asia' && item.filters.division === 'diamond');
for (const item of evidence.cases) {
  const changed = item.status === 200 ? item.raw.filter(row => {
    const other = diamond.raw.find(record => record.hero === row.hero);
    return !other || ['winrate', 'pickrate', 'banrate'].some(field => row[field] !== other[field]);
  }).length : '—';
  lines.push(`| ${item.filters.region}/${item.filters.division} | ${item.status} | ${Array.isArray(item.raw) ? item.raw.length : '—'} | ${item.status === 200 ? item.raw.filter(row => row.pickrate != null && row.pickrate < 1).length : '—'} | ${changed} |`);
}
lines.push('', `API 스키마의 grandmaster 설명은 champion 포함입니다. champion 단독 요청은 실제 HTTP ${evidence.unsupportedProbe?.status ?? '미검증'}입니다. 응답은 합산된 해당 버킷이며 내부 GM/Champion별 표본 비중이나 분리값은 제공되지 않아 독립 검증할 수 없습니다.`, '', '## 도미나·윈스턴·둠피스트·D.Mon 비교', '', '역할 내 순위와 S~D는 완전한 승률/픽률 집단에서 70:30으로 산정합니다. 백분위는 동률 평균 순위입니다.', '', '| 조건 | 영웅 | 승률% | 픽률% | 밴률% | 승률 백분위 | 픽률 백분위 | Meta | 역할 순위 | 티어 |', '| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |');
for (const cohort of cohorts.filter(item => ['all', 'diamond', 'master', 'grandmaster'].includes(item.filters.division))) {
  for (const hero of attachMetaTiers(heroes, cohort.records).filter(item => targets.includes(item.key))) lines.push(`| ${cohort.filters.region}/${cohort.filters.division} | ${hero.name} (${hero.key}) | ${n(hero.statistics?.winRate)} | ${n(hero.statistics?.pickRate)} | ${n(hero.statistics?.banRate)} | ${n(hero.winPercentile)} | ${n(hero.pickPercentile)} | ${n(hero.metaScore)} | ${hero.roleRank ?? '—'} | ${hero.tier ?? '미분류'} |`);
}
const baseline = attachMetaTiers(heroes, diamond.records);
lines.push('', '## 아시아 다이아몬드 가중치 민감도', '', `조건: ${filterLabel(diamond.filters)}. 70:30을 서비스 기본으로 유지합니다. 다른 비율은 분석용 비교이며 특정 영웅을 올리기 위한 보정은 하지 않았습니다.`, '', '| 승률:픽률 | 70:30 대비 역할 순위 변경 수 | 티어 변경 수 | 최대 순위 이동 |', '| --- | --- | --- | --- |');
const variants = [];
for (const winRate of [.7, .6, .5, .4, 1]) {
  const pickRate = 1 - winRate;
  const policy = { ...META_POLICY, weights: { winRate, pickRate } };
  const scored = attachMetaTiers(heroes, diamond.records, policy);
  lines.push(`| ${Math.round(winRate * 100)}:${Math.round(pickRate * 100)} | ${scored.filter((hero, i) => hero.roleRank !== baseline[i].roleRank).length}/${heroes.length} | ${scored.filter((hero, i) => hero.tier !== baseline[i].tier).length}/${heroes.length} | ${Math.max(...scored.map((hero, i) => Math.abs((hero.roleRank ?? 0) - (baseline[i].roleRank ?? 0))))} |`);
  variants.push({ label: `${Math.round(winRate * 100)}:${Math.round(pickRate * 100)}`, scored });
}
lines.push('', '| 영웅 | 70:30 | 60:40 | 50:50 | 40:60 | 100:0 비교 |', '| --- | --- | --- | --- | --- | --- |');
for (const key of targets) lines.push(`| ${key} | ${variants.map(variant => { const hero = variant.scored.find(item => item.key === key); return hero ? `${n(hero.metaScore)} · ${hero.roleRank}위/${hero.tier}` : '미제공'; }).join(' | ')} |`);
const winOnly = attachRoleTiers(heroes, diamond.records);
lines.push('', `기존 승률 단독 정책과 70:30 티어가 다른 영웅: ${baseline.filter((hero, i) => hero.tier !== winOnly[i].tier).length}/${heroes.length}명. 100:0 비교는 완전자료 집단의 백분위이며, 승률은 있으나 픽률이 없으면 기존 승률 단독 함수와 집단이 다를 수 있습니다.`, '', '## 향후 독립 등급 비교 예시: 겐지', '', '| 조건 | Meta | 역할 순위 | 티어 |', '| --- | --- | --- | --- |');
for (const row of compareHeroCohorts('genji', heroes, cohorts.filter(item => item.filters.region === 'asia' && ['gold', 'emerald', 'diamond', 'master', 'grandmaster'].includes(item.filters.division)))) lines.push(`| ${row.filters.division} | ${n(row.hero?.metaScore)} | ${row.hero?.roleRank ?? '—'} | ${row.hero?.tier ?? '미분류'} |`);
lines.push('', '밴률은 별도 관측값이며 점수에 합산하지 않습니다. 픽률은 인기이지 직접적인 성능 증거가 아닙니다. 낮은 픽률 경고는 정책일 뿐 표본 수·신뢰구간을 뜻하지 않습니다. 순위 차이는 가중치 민감도이며 실제 메타 강도·인과관계·예측 성능을 완벽하게 검증한 결과가 아닙니다. 이 문서는 수집 당시 결과이며 현재 화면은 실시간 API 응답으로 별도 계산합니다.', '');
await writeFile(new URL('../docs/RANKED-META-DATA.md', import.meta.url), lines.join('\n'));
console.log('Generated docs/RANKED-META-DATA.md');
console.log(JSON.stringify(baseline.filter(hero => targets.includes(hero.key)).map(hero => ({ key: hero.key, win: hero.statistics.winRate, pick: hero.statistics.pickRate, ban: hero.statistics.banRate, winPercentile: hero.winPercentile, pickPercentile: hero.pickPercentile, score: hero.metaScore, rank: hero.roleRank, tier: hero.tier })), null, 2));
